from flask import Flask, jsonify, request, Response

app = Flask(__name__)

TASKS = {1: {"id": 1, "title": "Купить молоко", "done": False}}
NEXT_ID = 2


@app.get("/api/tasks")
def list_tasks():
    return jsonify(list(TASKS.values()))


@app.post("/api/tasks")
def create_task():
    global NEXT_ID
    title = request.get_json(silent=True) or {}
    if not title.get("title"):
        return jsonify({"error": "поле title обязательно"}), 400
    task = {"id": NEXT_ID, "title": title["title"], "done": False}
    TASKS[NEXT_ID] = task
    NEXT_ID += 1
    response = jsonify(task)
    response.headers["Location"] = f"/api/tasks/{task['id']}"
    return response, 201


@app.put("/api/tasks/<int:task_id>")
def replace_task(task_id):
    task = TASKS.get(task_id)
    if task is None:
        return jsonify({"error": "задача не найдена"}), 404
    payload = request.get_json(silent=True)
    if payload is None:
        return jsonify({"error": "ожидали JSON в теле запроса"}), 400
    task.update({"title": payload.get("title", task["title"]),
                 "done": bool(payload.get("done", task["done"]))})
    return jsonify(task)


@app.delete("/api/tasks/<int:task_id>")
def delete_task(task_id):
    if TASKS.pop(task_id, None) is None:
        return jsonify({"error": "задача не найдена"}), 404
    return Response(status=204)


app.run(debug=True)

from flask import Flask, jsonify

app = Flask(__name__)


# Способ 1: заголовок вручную через after_request
@app.after_request
def add_cors_headers(response):
    response.headers["Access-Control-Allow-Origin"] = "http://localhost:3000"
    response.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization"
    response.headers["Access-Control-Allow-Methods"] = "GET, POST, PUT, PATCH, DELETE, OPTIONS"
    return response


@app.get("/api/tasks")
def list_tasks():
    return jsonify([{"id": 1, "title": "Купить молоко"}])


app.run(debug=True)

